DELIMITER $$
--
-- Procedimientos
--
DROP PROCEDURE IF EXISTS `sp_crear_plato`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_crear_plato` (IN `p_nombre` VARCHAR(100), IN `p_descripcion` TEXT, IN `p_precio` DECIMAL(10,2), IN `p_limite` INT, IN `p_imagen` MEDIUMBLOB, IN `p_activo` TINYINT, IN `p_usuario` VARCHAR(100))   BEGIN
  -- 1) Inserta en platos
  INSERT INTO platos 
    (nombre, descripcion, precio, limite_disponible, imagen, activo)
  VALUES 
    (p_nombre, p_descripcion, p_precio, p_limite, p_imagen, p_activo);

  -- 2) Registra en historial
  INSERT INTO historial 
    (fecha, usuario, accion, detalle)
  VALUES 
    (NOW(), p_usuario, 'crear', CONCAT('Creó plato: ', p_nombre));
END$$

DROP PROCEDURE IF EXISTS `sp_editar_plato`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_editar_plato` (IN `p_id` INT, IN `p_nombre` VARCHAR(100), IN `p_descripcion` TEXT, IN `p_precio` DECIMAL(10,2), IN `p_limite` INT, IN `p_imagen` MEDIUMBLOB, IN `p_activo` TINYINT, IN `p_usuario` VARCHAR(100))   BEGIN
  -- Actualiza con o sin imagen nueva
  IF p_imagen IS NULL THEN
    UPDATE platos
      SET nombre = p_nombre,
          descripcion = p_descripcion,
          precio = p_precio,
          limite_disponible = p_limite,
          activo = p_activo
    WHERE id_plato = p_id;
  ELSE
    UPDATE platos
      SET nombre = p_nombre,
          descripcion = p_descripcion,
          precio = p_precio,
          limite_disponible = p_limite,
          activo = p_activo,
          imagen = p_imagen
    WHERE id_plato = p_id;
  END IF;

  INSERT INTO historial 
    (fecha, usuario, accion, detalle)
  VALUES 
    (NOW(), p_usuario, 'editar', CONCAT('Editó plato: ', p_nombre));
END$$

DROP PROCEDURE IF EXISTS `sp_listar_pedidos`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_listar_pedidos` (IN `p_desde` DATE, IN `p_hasta` DATE)   BEGIN
  SELECT 
    p.fecha_reserva   AS fecha,
    a.nombre          AS alumno,
    p.carnet_alumno   AS carnet,
    p.descripcion_pedido AS descripcion,
    p.monto           AS monto
  FROM pedidos p
    JOIN alumnos a ON p.carnet_alumno = a.carnet
  WHERE p.fecha_reserva BETWEEN p_desde AND p_hasta
  ORDER BY p.fecha_reserva DESC;
END$$

DELIMITER ;

